```c
#include <stdio.h>
#include <string.h>

int suit_to_index(char s) {
    switch (s) {
        case 'C': return 0;
        case 'E': return 1;
        case 'U': return 2;
        case 'P': return 3;
        default:  return -1;
    }
}

int main(void) {
    char s[200];
    if (scanf("%199s", s) != 1) {
        return 0;
    }

    int count[4][14] = {0};
    int len = (int)strlen(s);

    for (int i = 0; i < len; i += 3) {
        int val = (s[i] - '0') * 10 + (s[i + 1] - '0');
        char suit = s[i + 2];
        int s_idx = suit_to_index(suit);
        if (s_idx >= 0 && val >= 1 && val <= 13) {
            count[s_idx][val]++;
        }
    }

    for (int k = 0; k < 4; k++) {
        int has_dup = 0;
        int distinct = 0;
        for (int v = 1; v <= 13; v++) {
            if (count[k][v] > 1) {
                has_dup = 1;
            }
            if (count[k][v] > 0) {
                distinct++;
            }
        }

        if (has_dup) {
            printf("erro\n");
        } else {
            printf("%d\n", 13 - distinct);
        }
    }

    return 0;
}
```

